const menu=document.querySelector('.menu'),nav=document.querySelector('.links');menu.addEventListener('click',()=>{const expanded=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(expanded));nav.classList.toggle('open',expanded)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');nav.classList.remove('open')}));document.getElementById('year').textContent=new Date().getFullYear();
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let visible=0;document.querySelectorAll('.gallery-card').forEach(card=>{card.hidden=filter!=='all'&&card.dataset.category!==filter;if(!card.hidden)visible++});document.getElementById('gallery-status').textContent='Showing '+visible+' concept'+(visible===1?'':'s')}));
const form=document.querySelector('.enquiry-form');if(form){for(const input of form.querySelectorAll('input[type=tel]'))input.addEventListener('input',()=>{const value=input.value.trim(),digits=value.replace(/\D/g,'');input.setCustomValidity(value&&(!/^[+()0-9 .-]+$/.test(value)||digits.length<7||digits.length>15)?'Enter a phone number with 7 to 15 digits.':'')});form.addEventListener('submit',event=>{for(const input of form.querySelectorAll('input[required]')){if(!input.value.trim()){input.value='';event.preventDefault();input.reportValidity();break}}});

}
// Reveal content once; preserve native touch, keyboard, zoom and reduced-motion behavior.
(()=>{const reduce=matchMedia('(prefers-reduced-motion: reduce)');const header=document.querySelector('header');const markHeader=()=>header.classList.toggle('scrolled',scrollY>20);addEventListener('scroll',markHeader,{passive:true});markHeader();const filename=location.pathname.split('/').pop()||'index.html';document.querySelectorAll('.links a').forEach(a=>{if(a.getAttribute('href')===filename)a.setAttribute('aria-current','page')});
if(!reduce.matches&&'IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.section-top,.service,.step,.planning-grid article,.inspiration-card,.gallery-card,.about-grid,.faq-grid,.visit-grid,.contact-grid,.enquiry-grid').forEach(el=>{el.classList.add('reveal-ready');observer.observe(el)});reduce.addEventListener('change',()=>{if(reduce.matches){observer.disconnect();document.querySelectorAll('.reveal-ready').forEach(el=>el.classList.add('is-visible'))}})}
const floatingEstimate=document.querySelector('.estimate-float'),footer=document.querySelector('footer');if(floatingEstimate&&footer&&'IntersectionObserver'in window){new IntersectionObserver(entries=>floatingEstimate.classList.toggle('footer-in-view',entries[0].isIntersecting),{threshold:.05}).observe(footer)}
let frame=0,target=scrollY,last=0;const root=document.documentElement;const stop=()=>{cancelAnimationFrame(frame);frame=0;root.classList.remove('flow-scrolling');target=scrollY};const tick=time=>{const dt=Math.min(40,time-last||16);last=time;const max=Math.max(0,root.scrollHeight-innerHeight);target=Math.max(0,Math.min(max,target));const delta=target-scrollY;if(Math.abs(delta)<.7){scrollTo(0,target);stop();return}scrollTo(0,scrollY+delta*(1-Math.exp(-dt/95)));frame=requestAnimationFrame(tick)};
addEventListener('wheel',event=>{if(reduce.matches||!matchMedia('(pointer: fine)').matches||event.ctrlKey||event.metaKey||event.shiftKey||Math.abs(event.deltaX)>Math.abs(event.deltaY)||!event.cancelable)return;let el=event.target instanceof Element?event.target:null;if(el?.closest('input,textarea,select,[contenteditable=true],dialog'))return;for(let p=el;p&&p!==document.body;p=p.parentElement){if(/auto|scroll/.test(getComputedStyle(p).overflowY)&&p.scrollHeight>p.clientHeight+1)return}if(!event.deltaY)return;event.preventDefault();if(!frame)target=scrollY;const amount=event.deltaY*(event.deltaMode===1?16:event.deltaMode===2?innerHeight:1);target=Math.max(0,Math.min(root.scrollHeight-innerHeight,target+amount));if(!frame){root.classList.add('flow-scrolling');last=performance.now();frame=requestAnimationFrame(tick)}},{passive:false});['pointerdown','touchstart','keydown'].forEach(type=>addEventListener(type,stop,{passive:true}));addEventListener('pagehide',stop);reduce.addEventListener('change',stop);
})();
